// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class PackedUnknownPriceDeclarationTest {

	@Test
	void unknownPricePreservesKnownAxesAndLogicalRowsWhenWorkIsUnknown() {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setOutputRowsPreservingPhysicalCost(17.0d);

		assertDoesNotThrow(() -> estimate.setInclusivePhysicalCostPreservingUnknown(
				Double.NaN, 2.0d, 3.0d, 4.0d, 5.0d, 6.0d, 7.0d, Double.NaN, 8.0d, 9.0d, Double.NaN));

		assertEquals(17.0d, estimate.outputRows());
		assertTrue(Double.isNaN(estimate.sequentialRows()));
		assertEquals(2.0d, estimate.randomSeeks());
		assertEquals(3.0d, estimate.iteratorOpens());
		assertEquals(4.0d, estimate.expressionEvaluations());
		assertEquals(5.0d, estimate.hashBuildRows());
		assertEquals(6.0d, estimate.hashProbeRows());
		assertEquals(7.0d, estimate.pathExpansions());
		assertTrue(Double.isNaN(estimate.resultRows()));
		assertEquals(8.0d, estimate.remoteCalls());
		assertEquals(9.0d, estimate.peakMemoryRows());
		assertTrue(Double.isNaN(estimate.workRows()));
		assertFalse(Double.isFinite(estimate.workRows()));
		assertEquals(PackedCostEstimate.CostScope.INCLUSIVE, estimate.costScope());
	}

	@Test
	void unknownPriceDoesNotReplaceCostFromFullyKnownAxes() {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setOutputRowsPreservingPhysicalCost(19.0d);

		assertDoesNotThrow(() -> estimate.setInclusivePhysicalCostPreservingUnknown(
				1.0d, 2.0d, 3.0d, 4.0d, 5.0d, 6.0d, 7.0d, 8.0d, 9.0d, 10.0d, Double.NaN));

		assertEquals(19.0d, estimate.outputRows());
		assertEquals(1.0d, estimate.sequentialRows());
		assertEquals(8.0d, estimate.resultRows());
		assertEquals(45.0d, estimate.workRows());
	}

	@Test
	void negativeAndInfiniteUnknownPhysicalPricesAreRejected() {
		PackedCostEstimate estimate = new PackedCostEstimate();
		assertThrows(IllegalArgumentException.class, () -> estimate.setInclusivePhysicalCostPreservingUnknown(
				1.0d, 2.0d, 3.0d, 4.0d, 5.0d, 6.0d, 7.0d, 8.0d, 9.0d, 10.0d, -1.0d));
		assertThrows(IllegalArgumentException.class, () -> estimate.setInclusivePhysicalCostPreservingUnknown(
				1.0d, 2.0d, 3.0d, 4.0d, 5.0d, 6.0d, 7.0d, 8.0d, 9.0d, 10.0d, Double.POSITIVE_INFINITY));
		assertThrows(IllegalArgumentException.class, () -> estimate.setInclusivePhysicalCostPreservingUnknown(
				1.0d, 2.0d, 3.0d, 4.0d, 5.0d, 6.0d, 7.0d, 8.0d, 9.0d, 10.0d, Double.NEGATIVE_INFINITY));
	}

	@Test
	void finiteOnlyInclusivePhysicalSetterStillRejectsUnknownAxes() {
		PackedCostEstimate estimate = new PackedCostEstimate();
		assertThrows(IllegalArgumentException.class, () -> estimate.setInclusivePhysicalCost(
				Double.NaN, 2.0d, 3.0d, 4.0d, 5.0d, 6.0d, 7.0d, 8.0d, 9.0d, 10.0d));
	}

	@Test
	void unknownPriceClearsPreviousObjectiveAndOnlyItsMetricKeys() {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setOutputRowsPreservingPhysicalCost(23.0d);
		estimate.setObjectiveInterval(2.0d, 3.0d, 5.0d);
		estimate.putPlannedDoubleMetric("unrelatedMetric", 29.0d);

		assertEquals(2.0d, estimate.objectiveLower());
		assertEquals(3.0d, estimate.objectivePoint());
		assertEquals(5.0d, estimate.objectiveUpper());
		assertTrue(estimate.plannedDoubleMetrics().containsKey("optimizer.objectiveLower"));
		assertTrue(estimate.plannedDoubleMetrics().containsKey("optimizer.objectivePoint"));
		assertTrue(estimate.plannedDoubleMetrics().containsKey("optimizer.objectiveUpper"));

		assertDoesNotThrow(() -> estimate.setInclusivePhysicalCostPreservingUnknown(
				Double.NaN, 2.0d, 3.0d, 4.0d, 5.0d, 6.0d, 7.0d, Double.NaN, 8.0d, 9.0d, Double.NaN));

		assertEquals(23.0d, estimate.outputRows());
		assertTrue(Double.isNaN(estimate.workRows()));
		assertTrue(Double.isNaN(estimate.objectiveLower()));
		assertTrue(Double.isNaN(estimate.objectivePoint()));
		assertTrue(Double.isNaN(estimate.objectiveUpper()));
		assertFalse(estimate.plannedDoubleMetrics().containsKey("optimizer.objectiveLower"));
		assertFalse(estimate.plannedDoubleMetrics().containsKey("optimizer.objectivePoint"));
		assertFalse(estimate.plannedDoubleMetrics().containsKey("optimizer.objectiveUpper"));
		assertEquals(29.0d, estimate.plannedDoubleMetrics().get("unrelatedMetric"));
		assertEquals(2.0d, estimate.randomSeeks());
		assertEquals(8.0d, estimate.remoteCalls());
	}

	@Test
	void unknownAxisWithKnownPositivePriceCreatesFiniteObjectiveInterval() {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setOutputRowsPreservingPhysicalCost(31.0d);

		assertDoesNotThrow(() -> estimate.setInclusivePhysicalCostPreservingUnknown(
				Double.NaN, 2.0d, 3.0d, 4.0d, 5.0d, 6.0d, 7.0d, 8.0d, 9.0d, 10.0d, 12.0d));

		assertEquals(31.0d, estimate.outputRows());
		assertTrue(Double.isNaN(estimate.sequentialRows()));
		assertEquals(12.0d, estimate.workRows());
		assertEquals(12.0d, estimate.objectiveLower());
		assertEquals(12.0d, estimate.objectivePoint());
		assertEquals(12.0d, estimate.objectiveUpper());
	}
}
